21	const { TypeScriptVersion } = require('@definitelytyped/typescript-versions');
22	const { typeScriptPath, install } = require('@definitelytyped/utils');
23	const { runTsCompile } = require('./pre-publish');
24	const globby = require('globby');
25	const semver = require('semver');
26	
27	const MIN_VERSION = '3.5.0';
28	
29	async function installTs() {
30	    const tsVersions = getTypeScriptVersions();
31	    for (const version of tsVersions) {
32	        await install(version);
33	    }
34	}
35	
36	async function runTests() {
37	    const compilerOptions = {
38	        declaration: false,
39	        importHelpers: false,
40	        sourceMap: false,
41	        pretty: false,
42	        removeComments: false,
43	        allowJs: false,
44	        outDir: __dirname + '/../test/types/tmp',
45	        typeRoots: [__dirname + '/../types/dist'],
46	        rootDir: __dirname + '/../test/types',
47	
48	        // Must pass in most strict cases
49	        strict: true
50	    };
51	    const testsList = await globby(__dirname + '/../test/types/*.ts');
52	
53	    const tsVersions = getTypeScriptVersions();
54	    for (const version of tsVersions) {
55	        console.log(`Testing ts version ${version}`);
56	        const ts = require(typeScriptPath(version));
57	        await runTsCompile(ts, compilerOptions, testsList);
58	
59	        console.log(`Finished test of ts version ${version}`);
60	    }
61	}
62	
63	function getTypeScriptVersions() {
64	    return TypeScriptVersion.unsupported
65	        .concat(TypeScriptVersion.shipped)
66	        .filter(version => semver.gte(version + '.0', MIN_VERSION));
67	}
68	
69	async function main() {
70	    await installTs();
71	    await runTests();
72	}
73	
74	module.exports = main;
75	
76	main();
