210	async function runTsCompile(localTs, compilerOptions, srcPathList) {
211	    // Must do it, because the value in tsconfig.json might be different from the inner representation.
212	    // For example: moduleResolution: "NODE" => moduleResolution: 2
213	    const {options, errors} = localTs.convertCompilerOptionsFromJson(compilerOptions, ecDir);
214	
215	    if (errors.length) {
216	        let errMsg = 'tsconfig parse failed: '
217	            + errors.map(error => error.messageText).join('. ')
218	            + '\n compilerOptions: \n' + JSON.stringify(compilerOptions, null, 4);
219	        assert(false, errMsg);
220	    }
221	
222	    // See: https://github.com/microsoft/TypeScript/wiki/Using-the-Compiler-API
223	
224	    let program = localTs.createProgram(srcPathList, options);
225	    let emitResult = program.emit();
226	
227	    let allDiagnostics = localTs
228	        .getPreEmitDiagnostics(program)
229	        .concat(emitResult.diagnostics);
230	
231	    allDiagnostics.forEach(diagnostic => {
232	        if (diagnostic.file) {
233	            let {line, character} = diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start);
234	            let message = localTs.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
235	            console.log(chalk.red(`${diagnostic.file.fileName} (${line + 1},${character + 1}): ${message}`));
236	        }
237	        else {
238	            console.log(chalk.red(localTs.flattenDiagnosticMessageText(diagnostic.messageText, '\n')));
239	        }
240	    });
241	    if (allDiagnostics.length > 0) {
242	        throw new Error('TypeScript Compile Failed');
243	    }
244	}
245	module.exports.runTsCompile = runTsCompile;
