264	/**
265	 * Transform import/require path in the entry file to `esm` or `lib`.
266	 */
267	function transformRootFolderInEntry(entryFile, replacement) {
268	    let code = fs.readFileSync(entryFile, 'utf-8');
269	    // Simple regex replacement
270	    // TODO More robust way?
271	    assert(
272	        !/(import\s+|from\s+|require\(\s*)["']\.\/echarts\./.test(code)
273	        && !/(import\s+|from\s+|require\(\s*)["']echarts\./.test(code),
274	        'Import echarts.xxx.ts is not supported.'
275	    );
276	    code = code.replace(/((import\s+|from\s+|require\(\s*)["'])\.\//g, `$1./${replacement}/`);
277	    fs.writeFileSync(
278	        entryFile,
279	        // Also transform zrender.
280	        singleTransformImport(code, replacement),
281	        'utf-8'
282	    );
283	}
