307	/**
308	 * 1. Transform zrender/src to zrender/lib
309	 * 2. Add .js extensions
310	 */
311	function singleTransformImport(code, replacement) {
312	    return transformImport(
313	        code.replace(/([\"\'])zrender\/src\//g, `$1zrender/${replacement}/`),
314	        (moduleName) => {
315	            // Ignore 'tslib' and 'echarts' in the extensions.
316	            if (moduleName === 'tslib' || moduleName === 'echarts') {
317	                return moduleName;
318	            }
319	            else if (moduleName === 'zrender/lib/export') {
320	                throw new Error('Should not import the whole zrender library.');
321	            }
322	            else if (moduleName.endsWith('.ts')) {
323	                // Replace ts with js
324	                return moduleName.replace(/\.ts$/, '.js');
325	            }
326	            else if (moduleName.endsWith('.js')) {
327	                return moduleName;
328	            }
329	            else {
330	                return moduleName + '.js'
331	            }
332	        }
333	    );
334	}
